    this.kitaplar = new Map();
  }

  ekle(isbn, baslik, yazar) {
    if (!isbn || !baslik) {
      throw new Error('ISBN ve başlık zorunlu');
    }
    if (this.kitaplar.has(isbn)) {
      throw new Error(`Bu ISBN zaten kayıtlı: ${isbn}`);
