    }
    this.kitaplar.set(isbn, { isbn, baslik, yazar: yazar || 'bilinmiyor', oduncte: false, kimde: null });
    return this.kitaplar.get(isbn);
  }

  bul(isbn) {
    return this.kitaplar.get(isbn) || null;
  }

  sil(isbn) {
    return this.kitaplar.delete(isbn);
  }

  oduncVer(isbn, kisi) {
    const kitap = this.kitaplar.get(isbn);
    if (!kitap) {
      throw new Error(`Böyle bir ISBN kayıtlı değil: ${isbn}`);
    }
    if (!kisi) {
      throw new Error('Kişi zorunlu');
    }
    if (kitap.oduncte) {
      throw new Error(`Bu kitap zaten ödünçte (${kitap.kimde}): ${isbn}`);
    }
    kitap.oduncte = true;
    kitap.kimde = kisi;
    return kitap;
  }

  iadeAl(isbn) {
